SELECT row_number() over () AS _uid_,* FROM (WITH target_line AS (     SELECT         line_id,         line_name,         geom     FROM bj_life.transit_line     WHERE line_id = 25 ) SELECT     ROW_NUMBER() OVER (         ORDER BY p.poi_id     )::integer AS objectid,      p.poi_id,     p.name,     p.address,     c.service_class_name,      ROUND(         ST_Distance(             p.geom,             t.geom         )::numeric,         1     ) AS distance_to_line_m,      p.geom::geometry(Point, 4509) AS geom  FROM bj_life.service_poi p JOIN bj_life.service_category c   ON p.category_id = c.category_id CROSS JOIN target_line t  WHERE p.geom IS NOT NULL   AND ST_DWithin(p.geom, t.geom, 500)
) AS _subq_1_
